"use client";
import React, { useState, useEffect } from "react";
import { Ruler, ArrowRightLeft, Eye, Shirt, Footprints, Info } from "lucide-react";
import { sizeData } from "@/data/sizes";

export default function SizeGuidePage() {
  const [activeCat, setActiveCat] = useState<keyof typeof sizeData>("footwear");
  const [baseUnit, setBaseUnit] = useState("");
  const [targetUnit, setTargetUnit] = useState("");

  useEffect(() => {
    const availableUnits = sizeData[activeCat].units;
    setBaseUnit(availableUnits[0]);
    setTargetUnit(availableUnits[availableUnits.length - 1]);
  }, [activeCat]);

  const categories = [
    { id: "footwear", label: "Footwear", icon: <Footprints size={14} /> },
    { id: "apparel", label: "Apparel", icon: <Shirt size={14} /> },
    { id: "crocs", label: "Crocs", icon: <span className="text-[10px] font-black">C</span> },
  ];

  return (
    <div className="bg-background text-foreground min-h-screen pb-20 selection:bg-brand selection:text-brand-foreground">
      
      {/* 1. MINIMALIST HEADER */}
      <section className="pt-10 pb-8 px-6 text-center space-y-4">
        <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-background-muted border border-border text-[9px] font-black uppercase tracking-[0.3em]">
          <Ruler size={10} className="text-brand" /> Size Architect
        </div>
        <h1 className="text-5xl md:text-7xl font-black uppercase italic tracking-tighter leading-none">
          The <span className="text-foreground-subtle">Archive.</span>
        </h1>
      </section>

      {/* 2. CATEGORY SWITCHER (SINGLE LINE) */}
      <nav className="flex justify-center gap-2 px-6 mb-12 overflow-x-auto no-scrollbar">
        {categories.map((cat) => (
          <button
            key={cat.id}
            onClick={() => setActiveCat(cat.id as any)}
            className={`flex items-center gap-2 px-6 py-3 rounded-full text-[10px] font-black uppercase tracking-widest transition-all duration-300 border ${
              activeCat === cat.id 
                ? "bg-foreground text-background border-foreground shadow-2xl" 
                : "bg-transparent border-border opacity-40 hover:opacity-100"
            }`}
          >
            {cat.icon} {cat.label}
          </button>
        ))}
      </nav>

      <section className="max-w-4xl mx-auto px-4 md:px-6">
        <div className="bg-background-muted/30 backdrop-blur-sm rounded-[2.5rem] border border-border p-4 md:p-8">
          
          {/* 3. CONDENSED SELECTORS */}
          <div className="grid grid-cols-2 gap-2 mb-6">
            <div className="space-y-1">
              <p className="text-[8px] font-black uppercase tracking-widest opacity-40 ml-4">I know my</p>
              <select 
                value={baseUnit} 
                onChange={(e) => setBaseUnit(e.target.value)}
                className="w-full bg-background border border-border rounded-2xl py-4 px-5 text-[10px] font-black uppercase outline-none focus:border-brand transition-colors appearance-none cursor-pointer"
              >
                {sizeData[activeCat].units.map((u: string) => <option key={u}>{u}</option>)}
              </select>
            </div>
            <div className="space-y-1">
              <p className="text-[8px] font-black uppercase tracking-widest opacity-40 ml-4">Convert to</p>
              <select 
                value={targetUnit} 
                onChange={(e) => setTargetUnit(e.target.value)}
                className="w-full bg-background border border-border rounded-2xl py-4 px-5 text-[10px] font-black uppercase outline-none focus:border-brand transition-colors appearance-none cursor-pointer"
              >
                {sizeData[activeCat].units.map((u: string) => <option key={u}>{u}</option>)}
              </select>
            </div>
          </div>

          {/* 4. RESPONSIVE DATA GRID (Replacing Table for better mobile UX) */}
          <div className="space-y-2">
            <div className="flex justify-between px-6 py-2 opacity-30 text-[9px] font-black uppercase tracking-widest">
              <span>{baseUnit}</span>
              <span>{targetUnit}</span>
            </div>
            
            <div className="space-y-1">
              {sizeData[activeCat].chart.map((row: any, i: number) => (
                <div 
                  key={i} 
                  className="flex items-center justify-between bg-background border border-border hover:border-brand/50 rounded-2xl px-6 py-5 transition-all group hover:scale-[1.01]"
                >
                  <span className="text-xl font-black italic tracking-tighter group-hover:text-brand transition-colors">
                    {row[baseUnit]}
                  </span>
                  <div className="flex items-center gap-3">
                    <ArrowRightLeft size={12} className="opacity-10" />
                    <span className="text-xl font-black italic tracking-tighter text-foreground-subtle">
                      {row[targetUnit]}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* 5. MINIMALIST FOOTER NOTE */}
        <div className="mt-12 flex flex-col md:flex-row items-center justify-between gap-6 px-4">
          <div className="flex items-center gap-3 opacity-40">
            <Info size={14} />
            <p className="text-[10px] font-medium uppercase tracking-tighter italic">
              Values based on global standards. Some fits vary by drop.
            </p>
          </div>
          <button className="text-[10px] font-black uppercase tracking-widest border-b-2 border-brand pb-1 hover:text-brand transition-colors">
            Request Custom Fitting
          </button>
        </div>
      </section>
    </div>
  );
}